const ch = await conn.createConfirmChannel();
await ch.assertQueue("orders", { durable: true, arguments: { "x-queue-type": "quorum" } });
ch.publish(exchange, "orders.created", Buffer.from(payload),
           { persistent: true, messageId: order.id });
await ch.waitForConfirms();            // resolves only after the broker persisted it
await ch.consume("orders", async (msg) => {
  await save(msg);                     // business commit
  ch.ack(msg);                         // then the delivery ack
}, { noAck: false });

