const producer = kafka.producer({
  transactionalId: "orders-tx-1", idempotent: true, maxInFlightRequests: 1,
});
await producer.connect();
const tx = await producer.transaction();
try {
  await tx.send({ topic: "orders.out", messages: [{ key: order.id, value: payload }] });
  await tx.commit();                   // nothing is visible before this
} catch (e) { await tx.abort(); }
